    write_u16(missing.state.window, 2U, 0x7777U);
    write_u16(missing.state.window, 4U, 21U);
    write_u16(missing.state.window, 6U, 15U);
    write_u16(missing.state.window, 8U, OP_1025);
    const auto missing_result = missing.step();
