        fixture.state.music_first_stream = 41U;
        fixture.state.music_second_stream = 42U;
        fixture.state.music_control_flags = 0x008300A5U;
        fixture.state.current_first_stream = 2U;
        fixture.state.current_stream_fade_divisor = 9U;
